        p.move(to: first)
        for q in silhouette.dropFirst() { p.addLine(to: q) }
        p.closeSubpath()
        return p
    }()

    /// Scale + centre the authored box into a view of `size`.
    static func transform(in size: CGSize, headroom: CGFloat = 1.06) -> CGAffineTransform {
        let s = min(size.width / box.width, size.height / (box.height * headroom)) * 0.985
        let dx = (size.width - box.width * s) / 2 - box.minX * s
        let dy = (size.height - box.height * headroom * s) / 2 - box.minY * s
        return CGAffineTransform(translationX: dx, y: dy).scaledBy(x: s, y: s)
    }
}
